-- 0004_seed.sql
--
-- The site's current content, lifted out of `lib/` and into the database.
-- GENERATED by scripts/generate-seed.mjs — edit the data modules and
-- re-run that script rather than editing this file by hand.
--
-- Every statement is an upsert keyed on a natural key (slug, section key,
-- title), so re-running the file restores the seed without duplicating it
-- and without touching rows that were added later in the admin.

-- ============================================================
-- site_settings
-- ============================================================
update public.site_settings set
  name          = 'Alpha Mugisha',
  short_name    = 'Alpha',
  role          = 'Software Engineer',
  location      = 'Kigali, Rwanda',
  email         = 'tigerkev07@gmail.com',
  tagline       = 'I''m still learning — but I''m already building.',
  description   = 'Alpha Mugisha — a software and systems builder from Kigali, Rwanda, working across web platforms, embedded electronics and applied AI.',
  github_url    = 'https://github.com/AlphaMugisha',
  linkedin_url  = 'https://www.linkedin.com/in/',
  cv_path       = '/alpha-mugisha-cv.pdf',
  hero_badge    = 'Open to new work',
  hero_line_1   = 'Software',
  hero_line_2   = 'that actually',
  hero_line_3   = 'works.',
  hero_intro    = 'I''m still learning — but I''m already building. I build web platforms, embedded electronics and applied AI systems from Kigali, Rwanda.',
  about_body_md = 'My work begins with the data. Before a screen exists there is a schema, a set of roles, and a clear idea of who needs to do what. That discipline came from starting with hardware, where a system either behaves correctly or visibly does not.

Since then I have built web platforms, REST APIs, administrative dashboards and connected devices — React, Next.js and TypeScript on the front, Node, Laravel and PHP behind them, over PostgreSQL, MySQL and SQLite.',
  portrait_path = '/images/portrait.jpg',
  portrait_alt  = 'Alpha Mugisha, Software Engineer',
  availability  = 'Open to new work'
where id;

-- ============================================================
-- sections
-- ============================================================
insert into public.sections (key, eyebrow, heading, accent, intro, sort_order) values
  ('about', 'Meet Alpha', 'Hello, I''m', 'Alpha.', '', 10),
  ('what-i-do', 'What I do', 'Built across the whole', 'stack, and below it.', 'From a database schema to a relay on a breadboard. I take ideas from concept to prototype to something other people can actually use, learning whatever the project needs on the way.', 20),
  ('work', 'Selected work', 'Real projects,', 'really shipped.', '', 30),
  ('work-grid', 'Everything', 'Click one to see how it was built.', '', '', 40),
  ('toolbox', 'Toolbox', 'The tools I', 'actually use.', 'No percentages anywhere — a rating out of ten would be invented, so each one says what it is used for instead.', 50),
  ('journey', 'How it developed', 'How I got', 'here.', 'Four stages, in the order they happened. Each one is still in use — the hardware habits did not stop being useful once the work moved to the web.', 60),
  ('beyond', 'How I work', 'Start with the data.', 'Finish with what ships.', 'Every metric on this site was read off a running system, not estimated. If a project has no verified numbers, it shows none — which is the same standard I hold the code to.', 70),
  ('github', 'On GitHub', 'What I''ve been', 'shipping lately.', 'Read live from the GitHub API — not a curated list.', 75),
  ('contact', 'Contact', 'Let''s build', 'something.', 'Freelance work, full-time roles, collaboration, or a question about how something here was built. I reply.', 80)
on conflict (key) do update set
  eyebrow = excluded.eyebrow, heading = excluded.heading,
  accent = excluded.accent, intro = excluded.intro, sort_order = excluded.sort_order;

-- ============================================================
-- projects
-- ============================================================
insert into public.projects (slug, name, year, summary, problem, solution, evidence, repo_url, status, categories, stack, stats, cover_path, is_featured, is_published, sort_order) values
  ('rwasport', 'RwaSport', '2026', 'A digital backbone for Rwandan sport - federations, clubs, schools, fixtures and results in one system instead of scattered spreadsheets.', 'Rwandan sport runs on disconnected records. Federations, clubs and schools each keep their own fixtures, squads and results, so there is no single place to answer a basic question like who played, who scored, and what the standings actually are.', 'A monorepo platform with a typed API over PostgreSQL and a mobile-first client. It models the real hierarchy - sports, federations, leagues, teams, players, fixtures, events and standings - with role-scoped access so a federation admin only sees their own sport, and a live match centre that updates as events are reported.', 'Counts read from the running rnsp_db instance and git history.', 'https://github.com/couper117/platform', 'in-progress'::project_status, array['Sports Technology', 'Platform', 'Digital Infrastructure']::text[], array['React', 'Vite', 'TypeScript', 'Express', 'Prisma', 'PostgreSQL', 'Tailwind CSS']::text[], '[{"label":"Data models","value":"43"},{"label":"Teams seeded","value":"13"},{"label":"Fixtures","value":"37"},{"label":"Commits","value":"622"}]'::jsonb, '/images/projects/rwasport.jpg', true, true, 10),
  ('greenhouse-automation', 'Greenhouse Automation', '2026', 'An ESP32 reads its environment, decides what to do about it, and reports back to the cloud - closing the loop between a sensor and a real actuator.', 'A greenhouse drifts out of range long before anyone notices. Checking a thermometer by hand is not monitoring, and it certainly is not control - by the time you read the number, the damage is already happening.', 'An ESP32 samples temperature and humidity from a DHT sensor, renders live state to an OLED display, and switches a fan through a relay when readings cross threshold. Every reading is pushed to Supabase, so the physical system has a history you can actually query - the wiring and the software are one system, not two.', null, null, 'prototype'::project_status, array['IoT', 'Embedded Systems', 'Robotics']::text[], array['ESP32', 'C++', 'Arduino', 'DHT Sensor', 'OLED', 'Relay', 'Supabase']::text[], '[]'::jsonb, '/images/projects/greenhouse-automation.jpg', true, true, 20),
  ('clean-kigali', 'Clean Kigali', '2026', 'Community sanitation reporting for the City of Kigali - report an issue, track it, and let administrators triage what comes in.', 'When something needs cleaning up, the report itself is the bottleneck. Complaints get made verbally, go unrecorded, and nobody can tell you whether anything was ever done about them.', 'A multilingual reporting service where residents file an issue and receive a tracking reference, while administrators work through a queue with status changes recorded in an audit log. Built server-rendered and deliberately light, so it stays usable on a slow connection.', 'Routes and audit logging verified against the running server.', 'https://github.com/AlphaMugisha/umuganda', 'in-progress'::project_status, array['Civic Technology', 'Environment', 'Web']::text[], array['TypeScript', 'Node.js', 'Express', 'MySQL', 'Tailwind CSS']::text[], '[{"label":"Locales","value":"Multi"},{"label":"Audit trail","value":"Yes"}]'::jsonb, '/images/projects/clean-kigali.jpg', true, true, 30),
  ('tembera', 'Tembera', '2026', 'A tourism guide to Rwanda built on a real catalogue of places - searchable, mappable, and structured rather than a brochure.', 'Information about where to go in Rwanda is scattered across posts and PDFs. None of it is structured, so none of it can be searched, filtered or mapped in a way a visitor can actually use while travelling.', 'A catalogue modelled properly - places, categories, subcategories and cities - behind a map view, a search view and an explore view, with saved places for signed-in users. The data model came first; the interface is a read of it.', 'Row counts read from the running tourism_db instance.', null, 'live'::project_status, array['Tourism', 'Product', 'Web Platform']::text[], array['Next.js', 'TypeScript', 'Prisma', 'PostgreSQL', 'Tailwind CSS']::text[], '[{"label":"Places","value":"495"},{"label":"Cities","value":"30"},{"label":"Categories","value":"87"}]'::jsonb, '/images/projects/tembera.jpg', true, true, 40),
  ('transiteco', 'TransitEco', '2026', 'Bus routes, schedules and seat booking behind a versioned REST API, with live vehicle location as a first-class concern.', 'Intercity bus travel is coordinated informally. Routes, departure times and remaining seats live in someone''s head or on a wall, which makes booking ahead - or knowing where a bus actually is - impossible.', 'A versioned Laravel API modelling companies, buses, routes, schedules and bookings, with role-based access for drivers and administrators and an endpoint for pushing live driver location. A separate Next.js client consumes it, so the API stands on its own.', 'Row counts read from the project database.', 'https://github.com/AlphaMugisha/Tega-Bus', 'prototype'::project_status, array['Transport', 'API Design', 'Web']::text[], array['Laravel', 'PHP', 'Next.js', 'TypeScript', 'SQLite', 'REST']::text[], '[{"label":"Routes","value":"8"},{"label":"Operators","value":"4"},{"label":"Buses","value":"6"}]'::jsonb, '/images/projects/transiteco.jpg', false, true, 50),
  ('digital-ikibina', 'Digital Ikibina', '2026', 'Rwanda''s rotating savings groups - ikibina - moved from a paper ledger into software, without losing how they actually work.', 'An ikibina runs on a shared notebook and collective memory. It works until a contribution is disputed, a payout order is questioned, or the person holding the book is unavailable - and then there is no record to appeal to.', 'A multilingual application that models members, contributions and payout cycles, with authentication so every entry is attributable. The design goal was to digitise the ledger without redesigning a social system that already works.', null, 'https://github.com/AlphaMugisha/digital-ikibina', 'in-progress'::project_status, array['FinTech', 'Community', 'Web Application']::text[], array['Next.js', 'TypeScript', 'Prisma', 'PostgreSQL', 'Auth.js', 'i18n']::text[], '[]'::jsonb, '/images/projects/digital-ikibina.jpg', false, true, 60),
  ('payment-system', 'Payment System', '2026', 'A multi-role payments application - customer, provider and admin - with webhook handling and a background job queue.', 'Payments are where a system''s edge cases live. A provider callback arrives twice, or arrives before the transaction is written, and a naive implementation quietly corrupts its own ledger.', 'Three role-scoped surfaces over a shared transaction model, with webhook events persisted before they are processed and a job queue handling the asynchronous work. Protected routes are enforced at the middleware layer rather than in the UI.', 'Verified against the running application and its database.', 'https://github.com/AlphaMugisha/payment-system', 'in-progress'::project_status, array['FinTech', 'Backend', 'Web Application']::text[], array['Next.js', 'TypeScript', 'Prisma', 'PostgreSQL', 'Auth.js']::text[], '[{"label":"Roles","value":"3"},{"label":"Providers","value":"3"}]'::jsonb, '/images/projects/payment-system.jpg', false, true, 70),
  ('school-systems', 'School & Community Systems', '2025 - 2026', 'A run of PHP/MySQL systems built for real institutions - school portals, a library, a church site and a restaurant point-of-sale.', 'Small institutions rarely get purpose-built software. They get a spreadsheet, or nothing, and the administrative work stays manual because the tools cost more than the problem appears to.', 'A series of complete systems built the direct way - PHP and MySQL on a normal stack - each with authentication, role separation and an admin surface. A school portal with staff and class records, a library with borrowing and role-based access, a content-managed church site, and a point-of-sale with stock batches and transfers.', 'Each system verified running locally against its own database.', 'https://github.com/AlphaMugisha/kami', 'live'::project_status, array['EdTech', 'PHP', 'Full Stack']::text[], array['PHP', 'MySQL', 'JavaScript', 'Tailwind CSS', 'Apache']::text[], '[{"label":"Systems shipped","value":"5"},{"label":"Roles modelled","value":"Staff / Student / Admin"}]'::jsonb, '/images/projects/school-systems.jpg', false, true, 80)
on conflict (slug) do update set
  name = excluded.name, year = excluded.year, summary = excluded.summary,
  problem = excluded.problem, solution = excluded.solution, evidence = excluded.evidence,
  repo_url = excluded.repo_url, status = excluded.status, categories = excluded.categories,
  stack = excluded.stack, stats = excluded.stats, cover_path = excluded.cover_path,
  is_featured = excluded.is_featured, sort_order = excluded.sort_order;

-- ============================================================
-- capabilities
-- ============================================================
-- `title` is not unique in the schema, so the upsert is expressed as a
-- delete-then-insert of the seeded titles only. Rows added in the admin
-- with other titles are left alone.
delete from public.capabilities where title in ('Full-stack web', 'Embedded systems', 'Applied AI', 'Databases & APIs', 'Robotics & IoT', 'Systems for institutions');
insert into public.capabilities (title, description, icon, tile, sort_order) values
  ('Full-stack web', 'Next.js, React and TypeScript over PostgreSQL and Prisma. Auth, uploads, dashboards and the unglamorous parts that make an app real.', 'Code2', 'accent'::tile_variant, 10),
  ('Embedded systems', 'ESP32 and Arduino with real sensors and actuators. Firmware that reads its environment, decides, and reports back to something online.', 'Cpu', 'ink'::tile_variant, 20),
  ('Applied AI', 'Models as engineering tools, not a talking point: API integration, coding agents, local inference and tool protocols like MCP.', 'Sparkles', 'accent-bright'::tile_variant, 30),
  ('Databases & APIs', 'Schemas with real constraints, role-scoped access, versioned REST endpoints and migrations that survive contact with production.', 'Database', 'ink'::tile_variant, 40),
  ('Robotics & IoT', 'Microcontrollers, relays, servos and RFID. Physical systems that move, with the cloud side built to match.', 'Bot', 'accent'::tile_variant, 50),
  ('Systems for institutions', 'School portals, libraries, point-of-sale. Small organisations rarely get purpose-built software — several of these were built so they could.', 'Workflow', 'accent-bright'::tile_variant, 60)
;

