-- `period` is the natural key for the seed but is not unique in the schema,
-- so the seeded periods are cleared first.
delete from public.journey_entries where period in ('Foundation', 'Early work', 'Current', 'Ongoing');
insert into public.journey_entries (period, title, discipline, body, highlights, image_path, sort_order) values
  ('Foundation', 'Electronics and embedded systems', 'Hardware', 'Began with microcontrollers and physical circuits — reading sensors, driving actuators, and learning to diagnose a system that gives no error message. This is where the habit of changing one variable at a time came from.', array['Arduino', 'ESP32', 'Sensors', 'Relays', 'Servos']::text[], '/images/journey/foundation.jpg', 10),
  ('Early work', 'Server-rendered web applications', 'Software', 'Moved into full applications with PHP and MySQL: authentication, role separation, administrative interfaces and reporting. Several were built for real institutions — schools, a library, a church, a restaurant.', array['PHP', 'MySQL', 'Authentication', 'Admin systems']::text[], '/images/journey/early-work.jpg', 20),
  ('Current', 'Modern platforms and APIs', 'Engineering', 'Now working primarily in TypeScript across React, Next.js, Node and Laravel, over PostgreSQL with Prisma. Larger systems with proper data models, versioned APIs, role-scoped access and multilingual interfaces.', array['TypeScript', 'Next.js', 'Prisma', 'PostgreSQL', 'REST APIs']::text[], '/images/journey/current.jpg', 30),
  ('Ongoing', 'Applied AI and automation', 'Practice', 'Using models as engineering tools rather than as a subject: API integration, coding agents, local inference and tool protocols such as MCP, applied to real workflows inside the projects above.', array['Claude', 'OpenAI', 'Ollama', 'MCP']::text[], '/images/journey/ongoing.jpg', 40)
;

